import{_ as t,o as n,c as i,a2 as r}from"./chunks/framework.vLhlLNVn.js";const g=JSON.parse('{"title":"Einstellungen (Instanz und Datenpunkt)","description":"","frontmatter":{"order":1,"adapter":"sourceanalytix","editLink":"https://github.com/DrozmotiX/ioBroker.sourceanalytix/edit/main/docs/de/03.referenz/01.einstellungen.md"},"headers":[],"relativePath":"de/adapter/sourceanalytix/referenz/einstellungen.md","filePath":"de/adapter/sourceanalytix/referenz/einstellungen.md","lastUpdated":null}'),d={name:"de/adapter/sourceanalytix/referenz/einstellungen.md"};function a(s,e,l,o,u,c){return n(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="einstellungen-instanz-und-datenpunkt" tabindex="-1">Einstellungen (Instanz und Datenpunkt) <a class="header-anchor" href="#einstellungen-instanz-und-datenpunkt" aria-label="Permalink to &quot;Einstellungen (Instanz und Datenpunkt)&quot;">​</a></h1><p><a id="units-supported-energy-volume-weight"></a></p><h2 id="welche-einheiten-werden-unterstutzt-energie-volumen-gewicht-lange" tabindex="-1">Welche Einheiten werden unterstützt (Energie, Volumen, Gewicht, Länge)? <a class="header-anchor" href="#welche-einheiten-werden-unterstutzt-energie-volumen-gewicht-lange" aria-label="Permalink to &quot;Welche Einheiten werden unterstützt (Energie, Volumen, Gewicht, Länge)?&quot;">​</a></h2><p><strong>Kurz:</strong> SourceAnalytix kennt 30 feste Einheiten für Leistung, Energie, Volumen, Masse und Länge. Umgerechnet wird nur innerhalb derselben Größe und zwischen Litern und Kubikmetern. Leistung wird über die Zeit zu Energie aufsummiert.</p><table tabindex="0"><thead><tr><th>Größe</th><th>Einheiten</th><th>Wird umgerechnet in</th></tr></thead><tbody><tr><td>Leistung</td><td><code>GW</code>, <code>MW</code>, <code>kW</code>, <code>W</code>, <code>mW</code></td><td>Energie (<code>GWh</code> bis <code>mWh</code>), über die Zeit aufsummiert</td></tr><tr><td>Energie</td><td><code>GWh</code>, <code>MWh</code>, <code>kWh</code>, <code>Wh</code>, <code>mWh</code></td><td>jede andere Energie-Einheit</td></tr><tr><td>Volumen (Kubik)</td><td><code>km³</code>, <code>m³</code>, <code>dm³</code>, <code>cm³</code>, <code>mm³</code></td><td>jede andere Volumen-Einheit, auch Liter</td></tr><tr><td>Volumen (Liter)</td><td><code>hl</code>, <code>l</code>, <code>dl</code>, <code>cl</code>, <code>ml</code></td><td>jede andere Volumen-Einheit, auch Kubikmeter (1 <code>m³</code> = 1.000 <code>l</code>)</td></tr><tr><td>Masse</td><td><code>t</code>, <code>kg</code>, <code>g</code></td><td>jede andere Masse-Einheit</td></tr><tr><td>Länge</td><td><code>km</code>, <code>m</code>, <code>dm</code>, <code>cm</code>, <code>mm</code>, <code>µm</code>, <code>nm</code></td><td>jede andere Länge-Einheit</td></tr></tbody></table><p>Bis v0.6.1 müssen die Zeichen genau so geschrieben sein: <code>m³</code> mit hochgestellter 3, <code>l</code> klein, <code>kWh</code> mit großem W. Welche Schreibweisen ab v0.6.2 zusätzlich erkannt werden, steht weiter unten.</p><h3 id="welche-einheit-gilt-wo" tabindex="-1">Welche Einheit gilt wo? <a class="header-anchor" href="#welche-einheit-gilt-wo" aria-label="Permalink to &quot;Welche Einheit gilt wo?&quot;">​</a></h3><p>Es gibt zwei Einheiten, und beide musst du kennen:</p><table tabindex="0"><thead><tr><th>Einstellung</th><th>Bedeutung</th></tr></thead><tbody><tr><td>„Einheit“ bei der Quelle (ab v0.7.0 in der Detailansicht, bis v0.6.x im Objekt-Dialog „Wählen Sie Einheit“)</td><td>Die Einheit, in der das Gerät den Wert <strong>liefert</strong> (Quelleinheit). Voreinstellung ist „Automatisch erkennen“: SourceAnalytix nimmt dann die Einheit, die am Objekt des Datenpunkts steht.</td></tr><tr><td>„Einheit“ in der Preisdefinition</td><td>Die Einheit, in der SourceAnalytix <strong>rechnet und anzeigt</strong> (Zieleinheit). Alle Verbrauchs-States, Startwerte und der Preis pro Einheit beziehen sich auf sie.</td></tr></tbody></table><p>Beispiele:</p><ul><li>Wasserzähler liefert <code>l</code>, Preisdefinition hat <code>m³</code>: aus 1.000 <code>l</code> werden 1 <code>m³</code>.</li><li>Stromzähler liefert <code>Wh</code>, Preisdefinition hat <code>kWh</code>: aus 1.000 <code>Wh</code> werden 1 <code>kWh</code>.</li><li>Steckdose liefert <code>W</code>, Preisdefinition hat <code>kWh</code>: SourceAnalytix rechnet die Leistung über die Zeit in Energie um.</li></ul><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Bei einer Leistungs-Quelle (<code>W</code>, <code>kW</code> …) muss die Preisdefinition eine Energie-Einheit haben (<code>kWh</code>, <code>Wh</code> …). Passen Quelle und Preisdefinition nicht zusammen, zum Beispiel <code>kg</code> und <code>kWh</code> oder <code>kWh</code> und <code>W</code>, rechnet SourceAnalytix bis v0.6.1 nichts und schreibt bei jedem Wert ins Log: <code>reading incorrect after conversion contact DEV</code>. Bei <code>W</code> und <code>m³</code> rechnet es ohne Meldung falsch. Ab v0.6.2 startet der Datenpunkt dann nicht, und im Log steht <code>Unit &lt;Einheit&gt; of &lt;Datenpunkt&gt; cannot be converted to unit &lt;Einheit&gt; of price definition &lt;Name&gt;</code>.</p></div><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Bis v0.6.1 rechnet SourceAnalytix die Einheiten <code>km³</code>, <code>dm³</code>, <code>cm³</code>, <code>mm³</code>, <code>µm</code> und <code>nm</code> falsch um, sobald Quelle und Preisdefinition verschiedene Einheiten haben. Beispiel: 1.000 <code>dm³</code> werden zu 100 <code>m³</code> statt zu 1 <code>m³</code>. Wähle bei diesen Einheiten in der Preisdefinition dieselbe Einheit wie am Datenpunkt. <code>m³</code>, die Liter-Reihe und die Umrechnung zwischen <code>l</code> und <code>m³</code> stimmen. Ab v0.6.2 ist der Fehler behoben (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1278" target="_blank" rel="noreferrer">#1278</a>).</p></div><h3 id="einheiten-außerhalb-der-liste" tabindex="-1">Einheiten außerhalb der Liste <a class="header-anchor" href="#einheiten-außerhalb-der-liste" aria-label="Permalink to &quot;Einheiten außerhalb der Liste&quot;">​</a></h3><p>Nicht unterstützt sind:</p><ul><li>Zählerstände ohne Einheit, also Stück oder Impulse,</li><li>Zeit, zum Beispiel Betriebsstunden in <code>h</code>,</li><li>Datenmengen wie <code>MB</code> oder <code>GB</code>,</li><li>Raten wie <code>m³/h</code>, <code>l/min</code> oder <code>kg/h</code>,</li><li>alle anderen Größen, zum Beispiel <code>%</code>, <code>hPa</code>, <code>V</code> oder <code>A</code>.</li></ul><p>Hat der Datenpunkt eine solche Einheit oder gar keine, startet er nicht, und im Log steht <code>No unit defined</code>. Wenn der Wert in Wahrheit in einer unterstützten Einheit vorliegt und nur das Objekt falsch beschriftet ist, wählst du die richtige Einheit selbst aus: ab v0.7.0 in der Detailansicht der Quelle unter „Einheit“ oder im Tab „Probleme“ bei „Einheit fehlt oder wird nicht erkannt“ mit „Beheben“, bis v0.6.x im Objekt-Dialog unter „Wählen Sie Einheit“. Wie das geht, steht unter <a href="./../fehlerbehebung/log-meldungen#error-unit-not-supported-no">Fehler „unit not supported“ / „No unit defined“</a>.</p><p><strong>Ab v0.7.0</strong> kommen Stück und Impulse dazu, siehe den nächsten Abschnitt. Zeit, Datenmengen, Raten wie <code>m³/h</code> und die übrigen Größen bleiben außerhalb der Liste.</p><h3 id="stuck-und-impulse-ab-v0-7-0" tabindex="-1">Stück und Impulse (ab v0.7.0) <a class="header-anchor" href="#stuck-und-impulse-ab-v0-7-0" aria-label="Permalink to &quot;Stück und Impulse (ab v0.7.0)&quot;">​</a></h3><p>Ab v0.7.0 gibt es zwei weitere Einheiten (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/304" target="_blank" rel="noreferrer">#304</a>, <a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/74" target="_blank" rel="noreferrer">#74</a>):</p><table tabindex="0"><thead><tr><th>Einheit</th><th>Wofür</th><th>Erkannte Schreibweisen am Objekt</th></tr></thead><tbody><tr><td><code>piece</code></td><td>Zählerstände ohne physikalische Einheit, zum Beispiel Brennerstarts, und Impulszähler mit Gesamtzahl der Impulse</td><td><code>pcs</code>, <code>pc</code>, <code>pieces</code>, <code>Stk</code>, <code>Stück</code>, <code>imp</code>, <code>impulse</code>, <code>pulses</code></td></tr><tr><td><code>piece/min</code></td><td>Impulse pro Minute, zum Beispiel <code>pulses/min</code> bei einem ESPHome-Impulszähler. SourceAnalytix summiert sie über die Zeit auf, wie eine Leistung.</td><td><code>pulses/min</code>, <code>imp/min</code>, <code>pcs/min</code></td></tr></tbody></table><p>So setzt du sie ein. Die Felder für Impulse stehen in der Detailansicht der Quelle: „Impulse pro &lt;Einheit&gt;“ im Bereich „Einstellungen“, sobald die Quelle in <code>piece</code> oder <code>piece/min</code> liefert und die Preisdefinition nicht in <code>piece</code> rechnet, „Jede Aktualisierung addiert ihren Wert“ unter „Für Experten“.</p><ul><li><strong>Nur zählen</strong>, zum Beispiel Brennerstarts: Lege eine Preisdefinition mit der Einheit <code>piece</code> an. Ein Preis pro Stück ist möglich, aber nicht nötig.</li><li><strong>Impulse in kWh oder m³ umrechnen:</strong> Trage bei „Impulse pro &lt;Einheit&gt;“ ein, wie viele Impulse eine Einheit der Preisdefinition ergeben, zum Beispiel <code>1000</code> für einen Stromzähler mit 1000 imp/kWh und eine Preisdefinition in kWh. Ohne diesen Wert startet die Quelle nicht, und im Log steht <code>Unit piece of &lt;Datenpunkt&gt; cannot be converted to unit kWh of price definition &lt;Name&gt;</code>.</li><li><strong>Jede Aktualisierung ist ein Impuls:</strong> Sendet der Datenpunkt keinen Zählerstand, sondern bei jedem Impuls ein Update, zum Beispiel <code>1</code>, <code>true</code> oder <code>0.001</code> kWh, setze den Haken „Jede Aktualisierung addiert ihren Wert“. Dann zählt jedes Update, auch wenn sich der Wert nicht ändert (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/479" target="_blank" rel="noreferrer">#479</a>). Negative Werte werden ignoriert, und der Wert, der beim Start von SourceAnalytix schon im Datenpunkt steht, zählt nicht noch einmal.</li></ul><p>Eine Quelle in <code>piece/min</code> und eine Quelle mit „Jede Aktualisierung addiert ihren Wert“ führen ihren Gesamtstand selbst, wie eine Leistungsquelle: Er beginnt bei 0, es gibt keine Reset-Erkennung, und Startwerte lässt du leer. Eine Quelle in <code>piece</code> mit Gesamtzahl der Impulse verhält sich wie ein Zählerstand, mit Reset-Erkennung.</p><p><strong>Ab v0.6.2:</strong> SourceAnalytix erkennt am Objekt auch abweichende Schreibweisen (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1264" target="_blank" rel="noreferrer">#1264</a>): <code>m3</code>, <code>M3</code> und <code>m^3</code> gelten als <code>m³</code>, <code>kwh</code> und <code>KWH</code> als <code>kWh</code>, <code>L</code> als <code>l</code>. Eine Schreibweise, die auf zwei Einheiten passt, wird nicht umgedeutet: <code>mwh</code> kann <code>MWh</code> oder <code>mWh</code> sein. Ausgeschriebene Namen wie <code>Liter</code> oder <code>Watt</code> erkennt SourceAnalytix auch weiterhin nicht. Wenn eine Schreibweise umgedeutet wird, steht im Log zum Beispiel <code>Unit &quot;m3&quot; of &lt;Datenpunkt&gt; is used as m³</code>. Auch der Einstellungsdialog nimmt diese Schreibweisen bei „Automatisch erkennen“ an (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1278" target="_blank" rel="noreferrer">#1278</a>).</p><p><strong>Siehe auch:</strong> <a href="./../anleitungen/quellen-und-einheiten#unit-datapoint-kwh-wh-m3">Welche Einheit stelle ich am Datenpunkt ein?</a> · <a href="./../erste-schritte/erster-zaehler#start-values-unit">Startwerte und ihre Einheit</a> · <a href="./../hintergrund/berechnung#sourceanalytix-convert-watts-kwh">Wie rechnet SourceAnalytix Watt in kWh um?</a></p><p><a id="instance-settings-exist-periods-decimals"></a></p><h2 id="welche-instanz-einstellungen-gibt-es-perioden-nachkommastellen" tabindex="-1">Welche Instanz-Einstellungen gibt es (Perioden, Nachkommastellen)? <a class="header-anchor" href="#welche-instanz-einstellungen-gibt-es-perioden-nachkommastellen" aria-label="Permalink to &quot;Welche Instanz-Einstellungen gibt es (Perioden, Nachkommastellen)?&quot;">​</a></h2><p><strong>Kurz:</strong> Die Instanz-Einstellungen von SourceAnalytix haben ab v0.7.0 vier Tabs. In „Haupteinstellungen“ legst du fest, welche Wochen-, Monats- und Quartals-States entstehen und wie viele Nachkommastellen neue Quellen bekommen. Fehlt ein State, ist meist die passende Option dort aus oder an der Quelle ist „Verbrauch“, „Kosten“ oder „Zählerstände speichern“ nicht gesetzt.</p><h3 id="die-tabs-ab-v0-7-0" tabindex="-1">Die Tabs (ab v0.7.0) <a class="header-anchor" href="#die-tabs-ab-v0-7-0" aria-label="Permalink to &quot;Die Tabs (ab v0.7.0)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tab</th><th>Inhalt</th><th>Wann wirkt eine Änderung</th></tr></thead><tbody><tr><td>„Übersicht“</td><td>Alle Quellen mit Status, Gesamtstand und den Werten für „Heute“, „Monat“ und „Jahr“. „Quelle hinzufügen“ startet den Assistenten, ein Klick auf eine Quelle öffnet ihre Detailansicht.</td><td>Aktionen mit ⚡ sofort, ohne Speichern und ohne Neustart</td></tr><tr><td>„Probleme“</td><td>Prüft alle Quellen und schlägt zu jedem Befund eine Lösung vor</td><td>sofort</td></tr><tr><td>„Preisdefinitionen“</td><td>Tabelle der Preise, siehe <a href="#price-definition-structured-categories-base">Wie ist eine Preisdefinition aufgebaut?</a></td><td>nach „Speichern“, die Instanz startet dabei neu</td></tr><tr><td>„Haupteinstellungen“</td><td>Jahresstatistik, laufendes Jahr, Rundung (siehe unten)</td><td>nach „Speichern“, die Instanz startet dabei neu</td></tr></tbody></table><p>„Übersicht“ und „Probleme“ fragen die laufende Instanz ab. Ist sie gestoppt, steht dort „Instanz läuft nicht“, und die Sofort-Aktionen sind gesperrt. Was die Detailansicht einer Quelle enthält, steht unter <a href="#datapoint-settings-costs-consumption-meter">Was bewirken die Einstellungen am Datenpunkt?</a>.</p><p><strong>Bis v0.6.x</strong> gibt es nur die Tabs „Haupteinstellungen“ und „Preisdefinitionen“. Quellen richtest du dort im Objekt-Dialog des Datenpunkts ein.</p><h3 id="tab-„haupteinstellungen" tabindex="-1">Tab „Haupteinstellungen“ <a class="header-anchor" href="#tab-„haupteinstellungen" aria-label="Permalink to &quot;Tab „Haupteinstellungen“&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Bereich</th><th>Option</th><th>Standard</th><th>Was SourceAnalytix anlegt</th></tr></thead><tbody><tr><td>„Jahresstatistik“</td><td>„Wochen“</td><td>aus</td><td>Archiv <code>&lt;Gerät&gt;.&lt;Jahr&gt;.&lt;Kategorie&gt;.weeks.01</code> bis <code>53</code></td></tr><tr><td>„Jahresstatistik“</td><td>„Monate“</td><td>an</td><td>Archiv <code>&lt;Gerät&gt;.&lt;Jahr&gt;.&lt;Kategorie&gt;.months.01_January</code> bis <code>12_December</code></td></tr><tr><td>„Jahresstatistik“</td><td>„Quartale“</td><td>aus</td><td>Archiv <code>&lt;Gerät&gt;.&lt;Jahr&gt;.&lt;Kategorie&gt;.quarters.Q1</code> bis <code>Q4</code></td></tr><tr><td>„Laufendes Jahr“</td><td>„Wochentag“</td><td>an</td><td><code>currentYear.&lt;Kategorie&gt;.currentWeek.01_Monday</code> bis <code>07_Sunday</code></td></tr><tr><td>„Laufendes Jahr“</td><td>„Wochen“</td><td>an</td><td><code>currentYear.&lt;Kategorie&gt;.weeks.01</code> bis <code>53</code></td></tr><tr><td>„Laufendes Jahr“</td><td>„Monate“</td><td>an</td><td><code>currentYear.&lt;Kategorie&gt;.months.01_January</code> bis <code>12_December</code></td></tr><tr><td>„Laufendes Jahr“</td><td>„Quartale“</td><td>an</td><td><code>currentYear.&lt;Kategorie&gt;.quarters.Q1</code> bis <code>Q4</code></td></tr><tr><td>„Laufendes Jahr“</td><td>„Vorheriger Zeitraum“</td><td>an</td><td><code>01_previousDay</code> bis <code>05_previousYear</code>, mit „Wochentag“ auch <code>previousWeek.01_Monday</code> bis <code>07_Sunday</code></td></tr><tr><td>„Rundung“</td><td>„Nachkommastellen für Verbrauchswerte“</td><td>3</td><td>Vorlage für neue Quellen</td></tr><tr><td>„Rundung“</td><td>„Nachkommastellen für Kostenwerte“</td><td>2</td><td>Vorlage für neue Quellen</td></tr></tbody></table><p><strong>Bis v0.6.x</strong> heißt die Option „Quartale“ in der deutschen Oberfläche „Viertel“.</p><p><code>&lt;Kategorie&gt;</code> ist <code>consumed</code> oder <code>delivered</code> für den Verbrauch, <code>costs</code> oder <code>earnings</code> für das Geld und <code>meterReadings</code> für Zählerstände. Ist eine der drei Optionen der „Jahresstatistik“ an, gibt es im Jahresordner zusätzlich die Jahressummen <code>&lt;Jahr&gt;.consumedCumulative</code> (oder <code>deliveredCumulative</code>), <code>&lt;Jahr&gt;.costsCumulative</code> (oder <code>earningsCumulative</code>) und den Zählerstand <code>&lt;Jahr&gt;.readingCumulative</code>. Was in den einzelnen States steht, beschreibt <a href="./states-und-meldungen#week-month-quarter-states-weekdays">Welche Wochen-, Monats- und Quartals-States gibt es?</a>.</p><h3 id="warum-manche-states-fehlen" tabindex="-1">Warum manche States fehlen <a class="header-anchor" href="#warum-manche-states-fehlen" aria-label="Permalink to &quot;Warum manche States fehlen&quot;">​</a></h3><ul><li><strong>Die Option ist aus.</strong> Dann legt SourceAnalytix die States nicht an. Schaltest du eine Option aus, löscht es die vorhandenen States des laufenden Jahres, sobald die Quelle das nächste Mal startet, also beim Neustart der Instanz nach dem Speichern.</li><li><strong>An der Quelle fehlt der Haken.</strong> Verbrauchs-States gibt es nur mit „Verbrauch“, Kosten-States nur mit „Kosten“, Zählerstände nur mit „Zählerstände speichern“.</li><li><strong>Die Woche gehört zum nächsten Jahr.</strong> Vom 29. bis 31. Dezember kann schon die Kalenderwoche 01 des neuen Jahres laufen. Sie wird unter <code>currentYear.&lt;Kategorie&gt;.weeks</code> nicht geschrieben, siehe <a href="./../hintergrund/perioden-und-zeit#week-52-53-have-values">Warum zeigt Woche 52/53 Werte im neuen Jahr?</a>.</li><li><strong>Der erste Periodenwechsel steht noch aus.</strong> Vorperioden-States stehen bis dahin auf 0, siehe <a href="./states-und-meldungen#yesterday-last-week-last-month">Wo finde ich gestern, letzte Woche, letzten Monat?</a>.</li></ul><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Schaltest du „Wochen“, „Monate“, „Quartale“, „Wochentag“ oder „Vorheriger Zeitraum“ aus, sind die Werte des laufenden Jahres in diesen States weg. Aufzeichnungen in einem History-Adapter und die Jahresordner früherer Jahre bleiben erhalten.</p></div><h3 id="nachkommastellen" tabindex="-1">Nachkommastellen <a class="header-anchor" href="#nachkommastellen" aria-label="Permalink to &quot;Nachkommastellen&quot;">​</a></h3><p>Die beiden Werte unter „Rundung“ sind nur eine Vorlage. Jede Quelle übernimmt sie einmal beim Anlegen und speichert ihre eigenen Nachkommastellen. Änderst du die Vorlage später, behalten vorhandene Quellen ihren Wert. Ab v0.7.0 änderst du die Stellen einer Quelle in ihrer Detailansicht unter „Für Experten“: „Nachkommastellen Verbrauch“ und „Nachkommastellen Kosten“.</p><ul><li>Erlaubt sind 0 bis 15. Mit -1 speichert SourceAnalytix den Wert ungerundet. Größere Zahlen gelten als 15, jede negative als -1.</li><li>Gerundet werden nur die geschriebenen States. Der Gesamtstand in <code>cumulativeReading</code> bleibt ungerundet.</li><li>Zählerstände unter <code>meterReadings</code> werden mit den Nachkommastellen für Verbrauchswerte gerundet.</li></ul><p><strong>Siehe auch:</strong> <a href="./../fehlerbehebung/falsche-werte-und-bekannte-fehler#so-many-decimals">Warum so viele Nachkommastellen?</a> · <a href="./states-und-meldungen#happens-turn-year">Was passiert beim Jahreswechsel?</a> · <a href="./../anleitungen/werte-auswerten#evaluate-across-years-adjusting-everything">Wie werte ich Werte über mehrere Jahre aus?</a></p><p><a id="datapoint-settings-costs-consumption-meter"></a></p><h2 id="was-bewirken-die-einstellungen-am-datenpunkt-costs-consumption-meter-values" tabindex="-1">Was bewirken die Einstellungen am Datenpunkt (Costs, Consumption, Meter values)? <a class="header-anchor" href="#was-bewirken-die-einstellungen-am-datenpunkt-costs-consumption-meter-values" aria-label="Permalink to &quot;Was bewirken die Einstellungen am Datenpunkt (Costs, Consumption, Meter values)?&quot;">​</a></h2><p><strong>Kurz:</strong> Jede Quelle hat eigene Einstellungen: Preisdefinition, Einheit und die Haken „Verbrauch“, „Kosten“ und „Zählerstände speichern“, die festlegen, welche States entstehen. Ab v0.7.0 stellst du sie beim Anlegen im Assistenten ein und änderst sie später in der Detailansicht der Quelle. „Übernehmen“ wirkt sofort, ohne Neustart.</p><h3 id="so-kommst-du-zu-den-einstellungen-ab-v0-7-0" tabindex="-1">So kommst du zu den Einstellungen (ab v0.7.0) <a class="header-anchor" href="#so-kommst-du-zu-den-einstellungen-ab-v0-7-0" aria-label="Permalink to &quot;So kommst du zu den Einstellungen (ab v0.7.0)&quot;">​</a></h3><ol><li>Öffne die Instanz-Einstellungen von SourceAnalytix, Tab „Übersicht“.</li><li>Klicke auf die Quelle. Die Detailansicht zeigt oben Datenpunkt, Art, Gesamtstand, Preis und „Letzte Aktualisierung“, darunter die Bereiche „Werte“, „Einstellungen“ und „Aktionen“.</li><li>Ändere im Bereich „Einstellungen“ die Felder. Weitere Felder stehen unter „Für Experten“.</li><li>Klicke auf „Übernehmen“. Ist ein Feld ungültig, markiert die Seite es und speichert nichts.</li></ol><h3 id="alle-einstellungen-einer-quelle" tabindex="-1">Alle Einstellungen einer Quelle <a class="header-anchor" href="#alle-einstellungen-einer-quelle" aria-label="Permalink to &quot;Alle Einstellungen einer Quelle&quot;">​</a></h3><p>Die Spalte „Standard“ nennt die Vorbelegung im Assistenten. Die letzte Spalte nennt für Umsteiger den Namen des Felds im Objekt-Dialog am Datenpunkt bis v0.6.x.</p><table tabindex="0"><thead><tr><th>Einstellung (ab v0.7.0)</th><th>Wirkung</th><th>Standard</th><th>Bis v0.6.x im Objekt-Dialog</th></tr></thead><tbody><tr><td>„Name“</td><td>Anzeigename des Ordners der Quelle. Ändert keine State-ID, siehe <a href="#name-datapoint-alias-output-id">Wie benenne ich den Datenpunkt?</a></td><td>Name des Datenpunkts</td><td>„Name“</td></tr><tr><td>„Einheit“</td><td>Einheit, in der der Datenpunkt liefert. „Automatisch erkennen“ nimmt die Einheit am Objekt, siehe <a href="#units-supported-energy-volume-weight">Welche Einheiten werden unterstützt?</a></td><td>erkannte Einheit</td><td>„Wählen Sie Einheit“</td></tr><tr><td>„Preisdefinition“</td><td>Pflicht. Legt die Zieleinheit fest und ob Verbrauch und Kosten oder Einspeisung und Erlös gezählt werden</td><td>–</td><td>„Preisdefinition auswählen“</td></tr><tr><td>„Verbrauch“</td><td>States unter <code>currentYear.consumed</code> oder <code>currentYear.delivered</code></td><td>an</td><td>„Verbrauch berechnen“</td></tr><tr><td>„Kosten“</td><td>States unter <code>currentYear.costs</code> oder <code>currentYear.earnings</code></td><td>an</td><td>„Kosten berechnen“</td></tr><tr><td>„Grundpreis einrechnen“</td><td>Bucht den „Preis pro Monat“ der Preisdefinition in die Kosten. Wirkt nur mit „Kosten“</td><td>an, wenn keine andere Quelle derselben Preisdefinition ihn schon bucht</td><td>„Inklusive Grundpreis“</td></tr><tr><td>„Zählerstände speichern“</td><td>Zählerstände je Periode unter <code>currentYear.meterReadings</code></td><td>an</td><td>„Zählerwerte speichern“</td></tr><tr><td>„Reset-Erkennung“</td><td>Fängt Sprünge des Zählers auf 0 ab, siehe <a href="#threshold-disabling-reset-detection-work">Threshold und Abschalten der Reset-Erkennung</a></td><td>nach der Frage „Springt der Wert manchmal auf 0 …?“</td><td>„Erkennung der Zurücksetzung des Gerätewerts Aktiviert“</td></tr><tr><td>„Negative Werte ignorieren“</td><td>Nur bei Leistung: Negative Werte zählen als 0 W, zum Beispiel bei Wechselrichtern in der Nacht</td><td>aus</td><td>„Negative Leistungswerte ignorieren“</td></tr><tr><td>„Schwelle Reset-Erkennung (&lt;Einheit&gt;)“ unter „Für Experten“</td><td>Größter Rückgang, der noch als Messschwankung gilt</td><td>1</td><td>„Schwelle“</td></tr><tr><td>„Nachkommastellen Verbrauch“ / „Nachkommastellen Kosten“ unter „Für Experten“</td><td>Rundung der geschriebenen States, siehe <a href="#instance-settings-exist-periods-decimals">Instanz-Einstellungen</a></td><td>Vorlage der Instanz (3 / 2)</td><td>„Nachkommastellen für Verbrauchswerte“ / „… Kostenwerte“</td></tr></tbody></table><p>Diese Einstellungen erscheinen nur bei passenden Quellen oder fragt der Assistent nicht ab. Ab v0.7.0 stehen sie alle in der Detailansicht (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1285" target="_blank" rel="noreferrer">#1285</a>):</p><table tabindex="0"><thead><tr><th>Einstellung</th><th>Wo in der Detailansicht</th><th>Wirkung</th><th>Standard</th></tr></thead><tbody><tr><td>„Technische ID“</td><td>unter „Für Experten“, auch im Assistenten</td><td>Name des Ordners <code>sourceanalytix.0.&lt;Gerät&gt;</code>. Erlaubt sind Buchstaben, Ziffern, <code>_</code> und <code>-</code>. Eine Änderung verschiebt alle Werte in den neuen Ordner, siehe <a href="#name-datapoint-alias-output-id">Wie benenne ich den Datenpunkt?</a></td><td>aus dem Namen gebildet</td></tr><tr><td>„Mittelwert bei Leistung“</td><td>bei Leistungsquellen, auch im Assistenten</td><td>Rechnet je Abschnitt mit dem Mittel aus altem und neuem Wert statt mit dem alten Wert</td><td>aus</td></tr><tr><td>„Maximale Lücke zwischen Leistungswerten (Minuten)“</td><td>bei Leistungsquellen</td><td>Längere Pausen ohne neuen Leistungswert zählen als 0 (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1266" target="_blank" rel="noreferrer">#1266</a>)</td><td>leer = aus</td></tr><tr><td>„Impulse pro &lt;Einheit&gt;“</td><td>bei Quellen in <code>piece</code> oder <code>piece/min</code>, deren Preisdefinition nicht in <code>piece</code> rechnet</td><td>Rechnet Impulse in die Zieleinheit um, zum Beispiel <code>1000</code> bei 1000 imp/kWh</td><td>leer</td></tr><tr><td>„Jede Aktualisierung addiert ihren Wert“</td><td>unter „Für Experten“</td><td>Jedes Update zählt als Zuwachs statt als Zählerstand</td><td>aus</td></tr><tr><td>„Startwerte“ „Tag“ bis „Jahr“</td><td>eigener Abschnitt „Startwerte“, im Assistenten nur bei Zählerstand</td><td>Gesamtstand zu Beginn der laufenden Periode, siehe <a href="./../erste-schritte/erster-zaehler#start-values-unit">Startwerte</a></td><td>leer = ab jetzt zählen</td></tr></tbody></table><p>Zahlen trägst du mit Komma oder Punkt ein. Ein einzelnes Komma oder ein einzelner Punkt ist immer das Dezimalzeichen: <code>1.283</code> heißt 1,283. Die Startwerte prüft die Detailansicht wie der Assistent; solange ein Startwert einen Fehler zeigt, bleibt „⚡ Übernehmen“ gesperrt.</p><p><strong>Ab v0.7.0:</strong> Im Objekt-Dialog am Datenpunkt (Reiter „Objekte“, Schraubenschlüssel) gibt es nur noch den Haken „aktiviert“, einen Hinweis und den Knopf „SourceAnalytix-Einstellungen öffnen“. Schaltest du eine Quelle dort ein, setzt SourceAnalytix „Verbrauch“, „Kosten“, „Zählerstände speichern“ und „Reset-Erkennung“ mit Schwelle 1. Weil noch keine Preisdefinition gewählt ist, erscheint die Quelle im Tab „Probleme“ mit „Keine Preisdefinition gewählt“. Bestehende Einstellungen bleiben dabei unverändert (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1286" target="_blank" rel="noreferrer">#1286</a>).</p><p><strong>Bis v0.6.x:</strong> Legst du eine Quelle im Objekt-Dialog neu an, sind „Verbrauch berechnen“, „Kosten berechnen“ und „Zählerwerte speichern“ nicht vorbelegt. Ohne diese Haken pflegt SourceAnalytix nur <code>cumulativeReading</code> und <code>statisticsJson</code>.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Nimmst du „Verbrauch“, „Kosten“ oder „Zählerstände speichern“ wieder heraus, löscht SourceAnalytix die zugehörigen States der Quelle. Aufzeichnungen in einem History-Adapter bleiben erhalten.</p></div><h3 id="wann-der-ordner-meterreadings-leer-bleibt" tabindex="-1">Wann der Ordner <code>meterReadings</code> leer bleibt <a class="header-anchor" href="#wann-der-ordner-meterreadings-leer-bleibt" aria-label="Permalink to &quot;Wann der Ordner `meterReadings` leer bleibt&quot;">​</a></h3><p><code>meterReadings</code> enthält den Gesamtstand am Ende einer Periode, nicht den Verbrauch. Er bleibt leer oder unvollständig, wenn:</p><ul><li>„Zählerstände speichern“ aus ist,</li><li>du den aktuellen Stand suchst: Einen State <code>meterReadings.01_currentDay</code> gibt es nicht, der aktuelle Stand steht in <code>cumulativeReading</code>,</li><li>in den Instanz-Einstellungen „Wochentag“, „Wochen“, „Monate“, „Quartale“ oder „Vorheriger Zeitraum“ aus sind, denn nur für diese Perioden entstehen Zählerstände,</li><li>der erste Periodenwechsel noch aussteht: <code>01_previousDay</code> und die anderen Vorperioden werden erst dann gefüllt.</li></ul><p><strong>Bis v0.6.1</strong> wird ein Zählerstand von genau 0 nicht unter <code>meterReadings</code> geschrieben. Ab v0.6.2 ist das behoben (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1253" target="_blank" rel="noreferrer">#1253</a>).</p><p><strong>Bis v0.6.x</strong> gibt es die Detailansicht nicht. Alle Einstellungen stehen dann im Objekt-Dialog am Datenpunkt, wie unter <a href="./../erste-schritte/erster-zaehler#configure-sourceanalytix-datapoint">Wo konfiguriere ich SourceAnalytix für einen Datenpunkt?</a> beschrieben.</p><p><strong>Siehe auch:</strong> <a href="./states-und-meldungen#meter-readings-cumulative">Warum sind Meter-Readings kumuliert?</a> · <a href="#source-types-exist-meter-power">Welche Quelltypen gibt es?</a> · <a href="./../fehlerbehebung/log-meldungen#datapoint-enabled-but-no-folders">Datenpunkt aktiviert, aber es entstehen keine Ordner</a></p><p><a id="threshold-disabling-reset-detection-work"></a></p><h2 id="wie-funktionieren-threshold-und-abschalten-der-reset-erkennung" tabindex="-1">Wie funktionieren Threshold und Abschalten der Reset-Erkennung? <a class="header-anchor" href="#wie-funktionieren-threshold-und-abschalten-der-reset-erkennung" aria-label="Permalink to &quot;Wie funktionieren Threshold und Abschalten der Reset-Erkennung?&quot;">​</a></h2><p><strong>Kurz:</strong> Die Reset-Erkennung und ihre Schwelle stellst du für jede Quelle einzeln ein. Lass die Erkennung an, wenn dein Zähler nach einem Neustart oder Stromausfall bei 0 beginnen kann. Die Schwelle (Standard 1, in der Zieleinheit) ist der größte Rückgang, der noch als Messschwankung gilt. Ausschalten ist nur für Quellen gedacht, die bewusst fallen dürfen.</p><h3 id="so-stellst-du-es-ein-ab-v0-7-0" tabindex="-1">So stellst du es ein (ab v0.7.0) <a class="header-anchor" href="#so-stellst-du-es-ein-ab-v0-7-0" aria-label="Permalink to &quot;So stellst du es ein (ab v0.7.0)&quot;">​</a></h3><ol><li>Öffne in den Instanz-Einstellungen, Tab „Übersicht“, die Quelle.</li><li>Setze oder entferne im Bereich „Einstellungen“ den Haken „Reset-Erkennung“.</li><li>Klicke auf „Für Experten“ und trage unter „Schwelle Reset-Erkennung (&lt;Einheit&gt;)“ die Schwelle in der Zieleinheit ein, zum Beispiel <code>0.5</code> für 0,5 kWh.</li><li>Klicke auf „Übernehmen“.</li></ol><p>Beim Anlegen fragt der Assistent: „Springt der Wert manchmal auf 0, z. B. nach einem Stromausfall?“ Mit „Ja“ ist die Reset-Erkennung an, mit „Nein“ aus. Vorgewählt ist „Nein“, bei Datenpunkten von Shelly oder Tasmota „Ja“.</p><h3 id="was-bei-einem-ruckgang-passiert" tabindex="-1">Was bei einem Rückgang passiert <a class="header-anchor" href="#was-bei-einem-ruckgang-passiert" aria-label="Permalink to &quot;Was bei einem Rückgang passiert&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Rückgang des Gerätewerts</th><th>Reset-Erkennung an</th><th>Reset-Erkennung aus</th></tr></thead><tbody><tr><td>höchstens die Schwelle</td><td>Messschwankung: Der Wert wird ignoriert, der Gesamtstand bleibt stehen</td><td>Der Gesamtstand fällt mit</td></tr><tr><td>mehr als die Schwelle</td><td>Möglicher Reset: SourceAnalytix wartet auf den nächsten Wert und rechnet dann mit einem neuen Offset weiter</td><td>Der Gesamtstand fällt mit, der Verbrauch der Perioden kann negativ werden</td></tr></tbody></table><p>Wie die Bestätigung eines Resets im Einzelnen abläuft, steht unter <a href="./../hintergrund/zaehler-reset#device-reset-detected-mean-reset">Was bedeutet „Device reset detected“?</a>. Eine Messschwankung steht nur im Debug-Log („Ignoring cumulative reading jitter“).</p><h3 id="welche-schwelle-passt" tabindex="-1">Welche Schwelle passt? <a class="header-anchor" href="#welche-schwelle-passt" aria-label="Permalink to &quot;Welche Schwelle passt?&quot;">​</a></h3><ul><li><strong>Größer als das normale Rauschen</strong> des Geräts, damit kleine Rückgänge nicht als Reset gelten.</li><li><strong>Kleiner als der Stand, mit dem das Gerät nach einem Reset oder Tausch wieder beginnt.</strong> Fällt ein Zähler nur knapp unter den alten Stand, wird er sonst nicht als Reset erkannt.</li><li><strong>0</strong> heißt: Jeder Rückgang ist ein möglicher Reset.</li></ul><p>Schwelle und Reset-Erkennung wirken nur bei Zählerständen. Bei Leistungsquellen (W), bei <code>piece/min</code> und bei „Jede Aktualisierung addiert ihren Wert“ führt SourceAnalytix den Gesamtstand selbst; dort gibt es keine Reset-Erkennung. Der Assistent zeigt die Schwelle bei Leistung deshalb nicht an.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Mit „Nein“ im Assistenten ist die Reset-Erkennung aus. Springt so ein Zähler doch einmal auf 0, fällt der Gesamtstand mit, und die Werte der laufenden Perioden werden negativ. Der Tab „Probleme“ meldet dann „Zähler springt auf 0, Reset-Erkennung ist aus“ und bietet „Einschalten“ an. Wie du die Werte danach korrigierst, steht unter <a href="./../anleitungen/zaehlerstaende-korrigieren#correct-wrong-too-high-negative">Falsche Werte korrigieren</a>.</p></div><p><strong>Ab v0.6.2:</strong> Die Meldung „Cumulative reading for … decreased while reset detection is disabled“ steht nur noch im Debug-Log. Bis v0.6.1 stand sie bei jedem Rückgang im Info-Log (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1262" target="_blank" rel="noreferrer">#1262</a>).</p><p><strong>Bis v0.6.x</strong> stellst du beides im Objekt-Dialog am Datenpunkt ein: „Erkennung der Zurücksetzung des Gerätewerts Aktiviert“ (Standard an) und „Schwelle“ (Standard 1).</p><p><strong>Siehe auch:</strong> <a href="./../anleitungen/zaehlerstaende-korrigieren#meter-restarts-after-power-loss">Mein Zähler startet nach Stromausfall bei 0</a> · <a href="./../hintergrund/zaehler-reset#counter-reset-0-daily-happens">Zähler, der täglich auf 0 zurückgesetzt wird</a> · <a href="./../anleitungen/zaehlerstaende-korrigieren#replaced-meter-device-avoid-negative">Zähler oder Gerät getauscht</a></p><p><a id="price-definition-structured-categories-base"></a></p><h2 id="wie-ist-eine-preisdefinition-aufgebaut-kategorien-grundpreis-dezimalzeichen" tabindex="-1">Wie ist eine Preisdefinition aufgebaut (Kategorien, Grundpreis, Dezimalzeichen)? <a class="header-anchor" href="#wie-ist-eine-preisdefinition-aufgebaut-kategorien-grundpreis-dezimalzeichen" aria-label="Permalink to &quot;Wie ist eine Preisdefinition aufgebaut (Kategorien, Grundpreis, Dezimalzeichen)?&quot;">​</a></h2><p><strong>Kurz:</strong> Eine Preisdefinition ist eine Zeile im Tab „Preisdefinitionen“ der Instanz-Einstellungen. Sie hat einen frei wählbaren Namen („Kategorie“), eine Einheit, eine Kostenart und einen Preis. Jede Quelle bekommt genau eine Preisdefinition. Der monatliche Grundpreis wird voll gebucht, einmal je Monat, nicht anteilig pro Tag.</p><h3 id="die-felder" tabindex="-1">Die Felder <a class="header-anchor" href="#die-felder" aria-label="Permalink to &quot;Die Felder&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Spalte</th><th>Bedeutung</th></tr></thead><tbody><tr><td>„Kategorie“</td><td>Name der Preisdefinition, zum Beispiel <code>Strom</code> oder <code>Waermepumpe</code>. Unter ihm wählst du sie an der Quelle aus. Jeder Name darf nur einmal vorkommen.</td></tr><tr><td>„Beschreibung“</td><td>Freier Text, nur für dich</td></tr><tr><td>„Kostenart“</td><td>„Kosten“ für Bezug (Verbrauch und Kosten) oder „Erträge“ für Einspeisung und Erlös. Bestimmt, ob die Werte unter <code>consumed</code> und <code>costs</code> oder unter <code>delivered</code> und <code>earnings</code> stehen.</td></tr><tr><td>„Einheit“</td><td>Die Zieleinheit: In ihr rechnet und zeigt SourceAnalytix alles für die Quellen dieser Preisdefinition</td></tr><tr><td>„Preisquelle“</td><td>„Festpreis“, „Datenpunkt“ oder „Tarifumschaltung“, siehe unten</td></tr><tr><td>„Preis pro Einheit“</td><td>Preis je Zieleinheit, zum Beispiel <code>0.32</code> für 0,32 €/kWh</td></tr><tr><td>„Preis-Datenpunkt“</td><td>Nur bei „Datenpunkt“ und „Tarifumschaltung“: der State, der den Preis oder den Tarif liefert</td></tr><tr><td>„Aktiver Tarifpreis“</td><td>Nur bei „Tarifumschaltung“: Preis, solange der Tarif aktiv ist</td></tr><tr><td>„Aktiver Auswahlwert“</td><td>Nur bei „Tarifumschaltung“: Wert des Preis-Datenpunkts, bei dem der Tarif aktiv ist</td></tr><tr><td>„Gültig ab“</td><td>Ab wann Preis und Grundpreis gelten, ab 0:00 Uhr dieses Tages</td></tr><tr><td>„Preis pro Monat“</td><td>Grundpreis je Monat</td></tr></tbody></table><p>Gibt es eine Kategorie doppelt, gilt nur die letzte Zeile. In State-IDs wird jedes Zeichen außer Buchstaben, Ziffern, <code>_</code> und <code>-</code> durch <code>_</code> ersetzt.</p><h3 id="preisquelle" tabindex="-1">Preisquelle <a class="header-anchor" href="#preisquelle" aria-label="Permalink to &quot;Preisquelle&quot;">​</a></h3><table tabindex="0"><thead><tr><th>„Preisquelle“</th><th>Woher der Preis kommt</th></tr></thead><tbody><tr><td>„Festpreis“</td><td>Aus „Preis pro Einheit“. Ein neuer Preis gilt ab „Gültig ab“ oder, ohne Datum, ab dem Speichern. Ältere Werte rechnet SourceAnalytix nicht von selbst neu.</td></tr><tr><td>„Datenpunkt“</td><td>Aus dem „Preis-Datenpunkt“, zum Beispiel einem dynamischen Strompreis in €/kWh. Jede Änderung wird mit ihrem Zeitstempel gespeichert. Ist der State beim Start leer, gilt „Preis pro Einheit“ als Ersatz.</td></tr><tr><td>„Tarifumschaltung“</td><td>Ein State schaltet zwischen „Preis pro Einheit“ und „Aktiver Tarifpreis“ um. Ohne „Aktiver Auswahlwert“ gilt der Tarif als aktiv bei <code>true</code>, bei einer Zahl ungleich 0 und bei jedem Text außer <code>0</code>, <code>false</code>, <code>off</code>, <code>no</code>, <code>closed</code> oder leer. Mit Auswahlwert muss der State genau diesen Wert haben.</td></tr></tbody></table><p>Ändert sich der Preis zwischen zwei Werten der Quelle, teilt SourceAnalytix den Verbrauch nach Zeit auf alten und neuen Preis auf. Wie du einen Preis ab einem Datum änderst und Kosten nachträglich neu rechnest, steht unter <a href="./../anleitungen/preise-und-kosten#costs-recalculated-change-price-change">Werden Kosten neu berechnet, wenn ich den Preis ändere?</a>. Dynamische Preise und Tag-/Nachttarif erklären <a href="./../anleitungen/preise-und-kosten#use-dynamic-electricity-price-tibber">Dynamischer Strompreis</a> und <a href="./../anleitungen/preise-und-kosten#bill-day-night-tariff">Tag-/Nachttarif</a>.</p><h3 id="grundpreis-voll-einmal-im-monat" tabindex="-1">Grundpreis: voll, einmal im Monat <a class="header-anchor" href="#grundpreis-voll-einmal-im-monat" aria-label="Permalink to &quot;Grundpreis: voll, einmal im Monat&quot;">​</a></h3><ul><li>Der „Preis pro Monat“ wird voll gebucht: einmal an dem Tag, ab dem er gilt, danach am 1. jedes Monats um 0:00 Uhr. Eine Verteilung auf die Tage gibt es nicht.</li><li>In den Tages- und Wochenwerten steht der ganze Betrag deshalb nur an dem Tag und in der Woche der Buchung.</li><li>Hast du kein „Gültig ab“ eingetragen, gilt der Grundpreis beim ersten Einrichten ab dem 1. Januar des laufenden Jahres. Der Jahreswert enthält dann alle Monate seit Januar.</li><li>Er zählt nur für Quellen mit „Grundpreis einrechnen“ und „Kosten“. Jede dieser Quellen bucht ihn voll. Haben zwei Quellen derselben Preisdefinition den Haken, zählt er doppelt.</li></ul><p><strong>Ab v0.7.0:</strong> Bucht schon eine andere Quelle den Grundpreis derselben Preisdefinition, warnen der Assistent und der Tab „Probleme“ („Grundpreis wird doppelt gebucht“, mit „Hier ausschalten“). Beim Start steht außerdem ein Hinweis im Log (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1268" target="_blank" rel="noreferrer">#1268</a>). Wie du den Grundpreis richtig zuordnest, steht unter <a href="./../anleitungen/preise-und-kosten#include-monthly-base-fee">Wie rechne ich einen monatlichen Grundpreis ein?</a>.</p><h3 id="komma-oder-punkt" tabindex="-1">Komma oder Punkt? <a class="header-anchor" href="#komma-oder-punkt" aria-label="Permalink to &quot;Komma oder Punkt?&quot;">​</a></h3><p>SourceAnalytix liest beide Schreibweisen: <code>0,32</code> und <code>0.32</code> ergeben denselben Preis. Das gilt für Preise aus der Tabelle, aus einem Preis-Datenpunkt und für geschriebene Werte in <code>currentPrice</code>. Lass den Tausenderpunkt weg. Ob der Preis richtig angekommen ist, siehst du nach dem Speichern im State <code>sourceanalytix.0.priceDefinitions.&lt;Kategorie&gt;.currentPrice</code>.</p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Ist ein Preis keine Zahl, rechnet SourceAnalytix mit 0 und schreibt <code>Price definition &lt;Kategorie&gt; has no valid unit price …, using 0 to avoid invalid cost calculations</code> ins Log. Die Kosten bleiben dann 0.</p></div><p>Eine neue oder geänderte Preisdefinition gilt erst nach „Speichern“, dabei startet die Instanz neu. Erst danach kannst du sie bei einer Quelle auswählen.</p><p><strong>Siehe auch:</strong> <a href="./../anleitungen/preise-und-kosten#assign-prices-create-custom-tariffs">Wie ordne ich Preise zu und lege eigene Tarife an?</a> · <a href="./states-und-meldungen#prices-read-written-as-states">Wie sind Preise als States lesbar und setzbar?</a> · <a href="./../fehlerbehebung/falsche-werte-und-bekannte-fehler#costs-stay-0-not-calculated">Kosten bleiben 0</a></p><p><a id="name-datapoint-alias-output-id"></a></p><h2 id="wie-benenne-ich-den-datenpunkt-alias-output-id" tabindex="-1">Wie benenne ich den Datenpunkt (Alias, Output-ID)? <a class="header-anchor" href="#wie-benenne-ich-den-datenpunkt-alias-output-id" aria-label="Permalink to &quot;Wie benenne ich den Datenpunkt (Alias, Output-ID)?&quot;">​</a></h2><p><strong>Kurz:</strong> Eine Quelle hat zwei Namen. Der „Name“ ist nur der Anzeigename und lässt sich jederzeit ändern. Die „Technische ID“ ist der Ordner <code>sourceanalytix.0.&lt;Gerät&gt;</code>, in dem alle States der Quelle liegen. Sie legst du am besten beim Anlegen fest, denn eine spätere Änderung zieht den ganzen Ordner um, und Skripte, VIS und History-Abfragen musst du dann anpassen.</p><table tabindex="0"><thead><tr><th></th><th>„Name“</th><th>„Technische ID“</th></tr></thead><tbody><tr><td>Wirkt auf</td><td>Anzeigename des Ordners und <code>source.name</code> in <code>statisticsJson</code></td><td>State-IDs: <code>sourceanalytix.0.&lt;Gerät&gt;.cumulativeReading</code>, <code>sourceanalytix.0.&lt;Gerät&gt;.currentYear.…</code></td></tr><tr><td>Im Assistenten (ab v0.7.0)</td><td>Schritt „Name“</td><td>unter „Für Experten“ im Schritt „Name“; vorbelegt aus dem Namen, zum Beispiel <code>strom_haus</code> aus „Strom Haus“</td></tr><tr><td>In der Detailansicht (ab v0.7.0)</td><td>„Name“ unter „Einstellungen“</td><td>„Technische ID“ unter „Einstellungen“, „Für Experten“</td></tr><tr><td>Bis v0.6.x im Objekt-Dialog</td><td>„Name“</td><td>„Ausgabe-ID“, vorbelegt aus der ID des Datenpunkts, Punkte werden zu <code>__</code></td></tr><tr><td>Leer gelassen</td><td>Name des Datenpunkts, ohne Namen <code>No name known, please provide alias</code></td><td>ID des Datenpunkts mit <code>__</code> statt Punkten</td></tr></tbody></table><h3 id="regeln-fur-die-technische-id" tabindex="-1">Regeln für die technische ID <a class="header-anchor" href="#regeln-fur-die-technische-id" aria-label="Permalink to &quot;Regeln für die technische ID&quot;">​</a></h3><ul><li>Erlaubt sind Buchstaben, Ziffern, <code>_</code> und <code>-</code>, höchstens 128 Zeichen. Der Vorschlag des Assistenten nutzt nur Kleinbuchstaben, Ziffern und <code>_</code>.</li><li>Die ID muss eindeutig sein. Nutzt sie schon eine andere Quelle, lässt sich nicht speichern („Diese ID nutzt schon eine andere Quelle.“).</li><li><code>info</code>, <code>priceDefinitions</code>, <code>priceHistory</code> und <code>basicPriceHistory</code> sind belegt, weil SourceAnalytix dort eigene States anlegt.</li></ul><h3 id="wenn-du-die-technische-id-anderst" tabindex="-1">Wenn du die technische ID änderst <a class="header-anchor" href="#wenn-du-die-technische-id-anderst" aria-label="Permalink to &quot;Wenn du die technische ID änderst&quot;">​</a></h3><p>Du änderst die ID in der Detailansicht der Quelle unter „Für Experten“ im Feld „Technische ID“ und klickst auf „⚡ Übernehmen“. Unter dem Feld steht dann „Beim Übernehmen werden alle Werte in den neuen Ordner verschoben. Skripte, Visualisierungen und Historien-Abfragen musst du anpassen.“ SourceAnalytix kopiert den ganzen Ordner mit allen Objekten und Werten unter die neue ID, prüft die Kopie und löscht erst danach den alten Ordner. Während der Kopie rechnet die Quelle nicht. Im Log steht <code>Migrated SourceAnalytix output for &lt;Datenpunkt&gt; from &lt;alte ID&gt; to &lt;neue ID&gt;</code>.</p><p>Klappt das nicht, behält SourceAnalytix die alte ID und meldet <code>Cannot use output ID &quot;&lt;neue ID&gt;&quot; for &lt;Datenpunkt&gt;: &lt;Grund&gt;; keeping &quot;&lt;alte ID&gt;&quot;</code>. Bricht die Instanz mitten im Umzug ab, räumt SourceAnalytix beim nächsten Start auf und versucht es erneut.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Nach dem Umzug zeigen Skripte, VIS-Views, Aliase und History-Abfragen noch auf die alte ID. Passe sie von Hand an. Werte, die ein History-Adapter vor dem Umzug aufgezeichnet hat, bleiben unter der alten ID gespeichert.</p></div><p>Einen anderen Datenpunkt als Quelle zu nutzen und die Daten zu behalten, ist noch nicht möglich. In der Detailansicht steht die Aktion „Datenpunkt wechseln“ deshalb als „geplant“ (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1271" target="_blank" rel="noreferrer">#1271</a>).</p><p><strong>Siehe auch:</strong> <a href="./../erste-schritte/erster-zaehler#values-consumption-today-yesterday">Wo finde ich meine Werte?</a> · <a href="./states-und-meldungen#migrating-older-versions-legacy-settings">Migration älterer Versionen und Altlasten</a> · <a href="./../anleitungen/werte-auswerten#read-sourceanalytix-values-script">Wie lese ich SourceAnalytix-Werte im Skript?</a></p><p><a id="source-types-exist-meter-power"></a></p><h2 id="welche-quelltypen-gibt-es-zahler-leistung" tabindex="-1">Welche Quelltypen gibt es (Zähler, Leistung)? <a class="header-anchor" href="#welche-quelltypen-gibt-es-zahler-leistung" aria-label="Permalink to &quot;Welche Quelltypen gibt es (Zähler, Leistung)?&quot;">​</a></h2><p><strong>Kurz:</strong> Es gibt zwei Arten von Quellen. Ein <strong>Zählerstand</strong> steigt immer weiter, SourceAnalytix rechnet den Verbrauch aus der Differenz. Eine <strong>Leistung</strong> zeigt den Momentanwert, SourceAnalytix summiert sie über die Zeit und führt den Gesamtstand selbst. Welche Art eine Quelle hat, ergibt sich aus ihrer Einheit.</p><table tabindex="0"><thead><tr><th></th><th>Zählerstand</th><th>Leistung</th></tr></thead><tbody><tr><td>Einheiten</td><td>Energie (<code>Wh</code>, <code>kWh</code> …), Volumen (<code>m³</code>, <code>l</code> …), Masse, Länge, <code>piece</code></td><td>Leistung (<code>W</code>, <code>kW</code> …) und <code>piece/min</code></td></tr><tr><td>Anzeige in der Detailansicht (ab v0.7.0)</td><td>„Zählerstand · kWh“</td><td>„Leistung · W → kWh“</td></tr><tr><td>Gesamtstand <code>cumulativeReading</code></td><td>Gerätewert + Offset</td><td>beginnt bei 0 und wächst mit jeder Messung</td></tr><tr><td>Reset-Erkennung und Schwelle</td><td>ja</td><td>nein</td></tr><tr><td>Startwerte</td><td>möglich</td><td>nicht nötig, lass sie leer</td></tr><tr><td>„Zählerstand angleichen“ (ab v0.7.0)</td><td>ja</td><td>ja</td></tr><tr><td>„Zähler getauscht“ (ab v0.7.0)</td><td>ja</td><td>nein</td></tr><tr><td>Eigene Optionen</td><td>–</td><td>„Negative Werte ignorieren“, „Mittelwert bei Leistung“, „Maximale Lücke zwischen Leistungswerten (Minuten)“</td></tr></tbody></table><p>Eine Quelle mit „Jede Aktualisierung addiert ihren Wert“ verhält sich wie eine Leistung: SourceAnalytix führt den Gesamtstand selbst, es gibt keine Reset-Erkennung und keine Startwerte.</p><p>Ob Bezug oder Einspeisung gezählt wird, hängt nicht vom Quelltyp ab, sondern von der „Kostenart“ der Preisdefinition: „Kosten“ füllt <code>consumed</code> und <code>costs</code>, „Erträge“ füllt <code>delivered</code> und <code>earnings</code>.</p><p>Beim Anlegen schlägt der Assistent im Schritt „Messart“ die Art aus der Einheit vor. Welchen Datenpunkt du nehmen solltest, wenn ein Gerät beides liefert, steht unter <a href="./../erste-schritte/erster-zaehler#datapoint-enable-meter-kwh-power">Zähler (kWh) oder Leistung (W)?</a>.</p><p><strong>Siehe auch:</strong> <a href="./../hintergrund/berechnung#sourceanalytix-convert-watts-kwh">Wie rechnet SourceAnalytix Watt in kWh um?</a> · <a href="#units-supported-energy-volume-weight">Welche Einheiten werden unterstützt?</a> · <a href="./../hintergrund/zaehler-reset#device-reset-detected-mean-reset">Was bedeutet „Device reset detected“?</a></p>',117)])])}const m=t(d,[["render",a]]);export{g as __pageData,m as default};
